import{_ as a,o as t,c as i,ag as e}from"./chunks/framework.BwSLX4ak.js";const k=JSON.parse('{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"shitbot/commands.md","filePath":"shitbot/commands.md"}'),d={name:"shitbot/commands.md"};function n(l,s,o,p,h,c){return t(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to &quot;命令与权限&quot;">​</a></h1><p>白名单管理命令 <code>/shitbot whitelist</code> 适用于全部平台，需要 <code>shitbot.admin</code>。使用 <code>/shitbot whitelist add - Steve</code> 添加无 QQ 白名单，使用 <code>/shitbot whitelist add 123456789 Steve</code> 直接添加 QQ 绑定。 删除、分页和 QQ 查询的完整语法见<a href="./api.html#管理员命令">插件 API 与白名单管理</a>。</p><h2 id="管理命令" tabindex="-1">管理命令 <a class="header-anchor" href="#管理命令" aria-label="Permalink to &quot;管理命令&quot;">​</a></h2><p>主命令为 <code>/shitbot</code>，别名为 <code>/sbot</code>。</p><table tabindex="0"><thead><tr><th>命令</th><th>功能</th><th>权限</th></tr></thead><tbody><tr><td><code>/shitbot status</code></td><td>查看数据库、OneBot 和运行状态</td><td>无</td></tr><tr><td><code>/shitbot reload</code></td><td>重载配置、数据库、OneBot、图片和命令服务</td><td><code>shitbot.admin</code></td></tr><tr><td><code>/shitbot update</code></td><td>下载并安装当前平台的新版本</td><td><code>shitbot.admin</code></td></tr><tr><td><code>/shitbot image</code></td><td>手动生成在线状态图片</td><td><code>shitbot.admin</code></td></tr><tr><td><code>/shitbot editor</code></td><td>生成高级图片模板编辑器的短时一次性登录地址</td><td><code>shitbot.admin</code></td></tr><tr><td><code>/shitbot migrate easybot [EasyBot.db]</code></td><td>导入 EasyBot 绑定数据</td><td><code>shitbot.admin</code></td></tr></tbody></table><p>Spigot 和 Nukkit-MOT 默认仅 OP 拥有 <code>shitbot.admin</code>。BungeeCord 与 Velocity 使用平台权限系统检查同名权限。</p><p><code>/shitbot reload</code> 会先创建新的运行实例；新配置加载失败时保留旧实例。插件 JAR 更新、Java 变更和 TLS 文件变更仍建议正常重启。</p><h2 id="qq-绑定" tabindex="-1">QQ 绑定 <a class="header-anchor" href="#qq-绑定" aria-label="Permalink to &quot;QQ 绑定&quot;">​</a></h2><p>默认别名：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>绑定 &lt;游戏ID&gt; &lt;验证码&gt;</span></span>
<span class="line"><span>/bind &lt;游戏ID&gt; &lt;验证码&gt;</span></span></code></pre></div><p>验证码由未绑定玩家进入服务器时生成。QQ 和游戏 ID 的绑定规则由 <code>binding</code> 配置控制。</p><h2 id="在线状态与背包" tabindex="-1">在线状态与背包 <a class="header-anchor" href="#在线状态与背包" aria-label="Permalink to &quot;在线状态与背包&quot;">​</a></h2><p>默认指令：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>服务器状态</span></span>
<span class="line"><span>在线人数</span></span>
<span class="line"><span>背包</span></span>
<span class="line"><span>我的背包</span></span>
<span class="line"><span>背包 &lt;游戏ID&gt;</span></span>
<span class="line"><span>我的背包 &lt;游戏ID&gt;</span></span></code></pre></div><p>指定游戏 ID 查询背包时，ShitBot 会确认该角色已绑定到消息发送者的 QQ，不能查询他人的角色。</p><h2 id="tps-指令" tabindex="-1">TPS 指令 <a class="header-anchor" href="#tps-指令" aria-label="Permalink to &quot;TPS 指令&quot;">​</a></h2><p>TPS 在 <code>commands.yml</code> 中配置：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><p>别名、成功文本和失败文本在所选语言文件的 <code>console.tps</code> 中配置。</p><ul><li>单服部署和 Nukkit-MOT 在本服查询。</li><li>代理部署可以在 <code>server</code> 中设置默认子服。</li><li>群成员也可以在指令后指定子服，例如 <code>TPS survival</code>。</li><li><code>permission</code> 为空时不检查游戏权限，但仍受群范围和命令冷却限制。</li></ul><h2 id="qq-快捷命令" tabindex="-1">QQ 快捷命令 <a class="header-anchor" href="#qq-快捷命令" aria-label="Permalink to &quot;QQ 快捷命令&quot;">​</a></h2><p>每个快捷命令放在 <code>commands.yml</code> 的 <code>shortcuts</code> 下：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">shortcuts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  luckperms-editor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    command</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;lp editor&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;shitbot.admin&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    allow-unbound</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;backend&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    capture-seconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span></code></pre></div><p>内置快捷命令的别名和回复模板在语言文件的 <code>console.shortcuts.&lt;名称&gt;</code> 中配置。新增自定义快捷命令时，如果语言文件中没有同名条目，会使用 <code>commands.yml</code> 中的 <code>aliases</code>、<code>message</code> 和 <code>failed</code> 作为后备。</p><table tabindex="0"><thead><tr><th>配置</th><th>说明</th></tr></thead><tbody><tr><td><code>aliases</code></td><td>QQ 群内触发文本</td></tr><tr><td><code>command</code></td><td>去掉前导 <code>/</code> 的控制台命令</td></tr><tr><td><code>permission</code></td><td>绑定角色必须拥有的游戏权限；留空表示跳过游戏权限检查</td></tr><tr><td><code>allow-unbound</code></td><td>是否允许未绑定 QQ 调用；默认关闭</td></tr><tr><td><code>target</code></td><td><code>backend</code> 在 Bukkit 子服执行，<code>proxy</code> 在 BungeeCord/Velocity 执行</td></tr><tr><td><code>server</code></td><td>默认目标子服；留空时优先使用绑定角色所在子服</td></tr><tr><td><code>capture-seconds</code></td><td>执行后等待并收集新增控制台日志的时间</td></tr></tbody></table><p>即使 <code>permission</code> 为空，默认仍要求发送者已经绑定游戏角色。只有明确设置 <code>allow-unbound: true</code> 才允许未绑定群成员执行，该配置会降低权限边界，应谨慎使用。</p><p>群成员可以在快捷命令后指定目标子服，例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lp编辑 survival</span></span></code></pre></div><p>该参数会覆盖命令中的 <code>server</code>。</p><h2 id="qq-高级图片命令" tabindex="-1">QQ 高级图片命令 <a class="header-anchor" href="#qq-高级图片命令" aria-label="Permalink to &quot;QQ 高级图片命令&quot;">​</a></h2><p>高级图片模板不自行注册命令。每个群入口必须在 <code>commands.yml</code> 的 <code>image-templates.commands</code> 中明确声明：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">image-templates</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  commands</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    player-card</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      aliases</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;我的名片&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;player-card&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      player-source</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;argument&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      target-server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;survival&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;shitbot.image.player-card&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      cooldown-seconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      usage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%at% 用法：我的名片 &lt;已绑定角色名&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      failed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%at% 图片生成失败：%result%&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>配置</th><th>说明</th></tr></thead><tbody><tr><td><code>aliases</code></td><td>群内触发文本；应避免与内置指令、TPS 或快捷命令重复</td></tr><tr><td><code>template</code></td><td>要渲染的已发布模板 ID</td></tr><tr><td><code>player-source</code></td><td><code>bound</code> 取最新绑定，<code>argument</code> 校验命令参数属于发送者，<code>none</code> 不读取绑定</td></tr><tr><td><code>target-server</code></td><td>代理部署中处理权限与 PAPI 的 Spigot 后端</td></tr><tr><td><code>permission</code></td><td>所选绑定角色必须拥有的游戏权限；留空跳过权限检查</td></tr><tr><td><code>cooldown-seconds</code></td><td>该模板命令独立的群号＋QQ 冷却</td></tr><tr><td><code>usage</code> / <code>failed</code></td><td>参数错误与生成失败回复；支持 <code>%at%</code>、<code>%result%</code>、<code>%command%</code> 和 <code>%server%</code></td></tr></tbody></table><p>权限请求只判断权限，不执行控制台命令。<code>player-source: none</code> 与非空 <code>permission</code> 不能组合成有效授权，因为没有游戏角色可供校验。该功能还要求 <code>config.yml</code> 中 <code>custom-image-templates.enabled: true</code>；完整说明见<a href="./image-templates.html">图片渲染与高级模板</a>。</p><h2 id="权限检查顺序" tabindex="-1">权限检查顺序 <a class="header-anchor" href="#权限检查顺序" aria-label="Permalink to &quot;权限检查顺序&quot;">​</a></h2><p>Spigot 后端执行带 <code>permission</code> 的快捷命令时：</p><ol><li>角色在线时使用 Bukkit 权限系统；</li><li>角色离线时依次尝试 LuckPerms、Vault 和离线 OP 状态。</li></ol><p>代理本地命令使用代理权限系统；离线权限可由代理上的 LuckPerms 提供。Nukkit-MOT 在线角色使用 Nukkit 权限系统，离线角色使用 LuckPerms（如已安装）。</p><h2 id="命令输出" tabindex="-1">命令输出 <a class="header-anchor" href="#命令输出" aria-label="Permalink to &quot;命令输出&quot;">​</a></h2><p>快捷命令执行前会记录日志位置，等待 <code>capture-seconds</code> 后读取这段时间新增的内容：</p><ul><li>Bukkit 使用 <code>logs/latest.log</code>；</li><li>Nukkit-MOT 使用 <code>logs/server.log</code>；</li><li>原始日志文件不会被修改；</li><li>单次回复最多保留 100 行、4000 个字符；</li><li>玩家聊天、上下线、执行命令等日志会从回复副本中移除；</li><li>玩家名、UUID、IP、Token、密码和数据库地址会在回复副本中脱敏。</li></ul><p>执行成功但没有产生新日志时，机器人会返回明确提示。</p><h2 id="修改后生效" tabindex="-1">修改后生效 <a class="header-anchor" href="#修改后生效" aria-label="Permalink to &quot;修改后生效&quot;">​</a></h2><p>保存 <code>commands.yml</code> 或语言文件后执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/shitbot reload</span></span></code></pre></div><p>如果是代理—后端部署，代理和相关后端的配置都修改完成后再分别重载。通道地址、证书或防火墙发生变化时建议重启。</p>`,46)])])}const g=a(d,[["render",n]]);export{k as __pageData,g as default};
